const WHO = { j: 'juna', b: 'brum', o: 'bolzen', z: 'zora' };
const EMO = { h: 'happy', c: 'curious', s: 'surprised', w: 'worried', a: 'angry', d: 'determined', z: 'sleepy', p: 'proud' };
// Kurzschreibweise: 'sprecher|gefühl|text'
const P = (arr) => arr.map((x) => { const [w, e, ...t] = x.split('|'); return { who: WHO[w], e: EMO[e] || e, t: t.join('|') }; });

const M = (o) => ({ map: 'fracht', ...o, intro: P(o.intro), win: P(o.win) });

