// Flache Liste mit Kapitel-Info und stabilen IDs.
export const MISSIONS = KAPITEL.flatMap((k) => k.missionen.map((m, i) => ({ ...m, kapitel: k.id, nr: i + 1, seed: SEED, erklaerung: '' }))).map((m, i) => ({ ...m, id: i + 1 }));
